create or replace function public.onboard_recruitment_company(p_name text,p_slug text,p_plan text default 'starter') returns uuid language plpgsql security definer set search_path=public as $$ declare v_uid uuid:=auth.uid(); v_company uuid; begin if v_uid is null then raise exception 'Authentication required'; end if; if exists(select 1 from public.profiles where id=v_uid) then raise exception 'Account already belongs to a company'; end if; if length(trim(p_name))<2 or p_slug !~ '^[a-z0-9][a-z0-9-]{1,48}[a-z0-9]$' then raise exception 'Invalid company name or slug'; end if; if not exists(select 1 from public.saas_plans where code=p_plan and active) then raise exception 'Invalid plan'; end if; insert into public.companies(name,slug,onboarding_completed_at) values(trim(p_name),lower(p_slug),now()) returning id into v_company; insert into public.profiles(id,company_id,role) values(v_uid,v_company,'owner'); insert into public.company_subscriptions(company_id,plan_code,status,trial_ends_at,current_period_start,current_period_end) values(v_company,p_plan,'trialing',now()+interval '14 days',now(),now()+interval '14 days'); return v_company; end $$; revoke all on function public.onboard_recruitment_company(text,text,text) from public,anon; grant execute on function public.onboard_recruitment_company(text,text,text) to authenticated;
create or replace function public.create_placement_invoice(p_placement uuid,p_issue_date date default current_date) returns uuid language plpgsql security definer set search_path=public as $$ declare v_uid uuid:=auth.uid(); v_company uuid; v_role text; p public.placements%rowtype; c public.client_contracts%rowtype; v_id uuid; v_number text; begin select company_id,role into v_company,v_role from public.profiles where id=v_uid; if v_company is null or v_role not in ('owner','manager') then raise exception 'Not authorised'; end if; select * into p from public.placements where id=p_placement and company_id=v_company for update; if not found then raise exception 'Placement not found'; end if; if exists(select 1 from public.invoices where placement_id=p.id and status<>'void') then raise exception 'Active invoice already exists'; end if; select * into c from public.client_contracts where id=p.contract_id and company_id=v_company; v_number:='TF-'||to_char(current_date,'YYYY')||'-'||lpad((select (count(*)+1)::text from public.invoices where company_id=v_company),5,'0'); insert into public.invoices(company_id,placement_id,client_id,number,status,currency,subtotal,tax_rate,tax_amount,total,issue_date,due_date,created_by) values(v_company,p.id,p.client_id,v_number,'draft',p.currency,p.fee_amount,p.vat_rate,p.vat_amount,p.total_amount,p_issue_date,p_issue_date+coalesce(c.payment_terms_days,14),v_uid) returning id into v_id; update public.placements set invoice_number=v_number,invoice_status='draft',invoiced_at=now(),due_at=(p_issue_date+coalesce(c.payment_terms_days,14))::timestamptz where id=p.id; return v_id; end $$; revoke all on function public.create_placement_invoice(uuid,date) from public,anon; grant execute on function public.create_placement_invoice(uuid,date) to authenticated;
create or replace function public.record_invoice_adjustment(p_invoice uuid,p_kind text,p_amount numeric,p_reason text,p_reference text default null) returns void language plpgsql security definer set search_path=public as $$ declare v_uid uuid:=auth.uid(); v_company uuid; v_role text; i public.invoices%rowtype; v_delta numeric; begin select company_id,role into v_company,v_role from public.profiles where id=v_uid; if v_company is null or v_role not in ('owner','manager') then raise exception 'Not authorised'; end if; if p_kind not in ('payment','credit','refund','write_off','correction') or p_amount<=0 or length(trim(p_reason))<3 then raise exception 'Invalid adjustment'; end if; select * into i from public.invoices where id=p_invoice and company_id=v_company for update; if not found or i.status='void' then raise exception 'Invoice unavailable'; end if; insert into public.invoice_adjustments(company_id,invoice_id,kind,amount,reason,reference,created_by) values(v_company,p_invoice,p_kind,p_amount,trim(p_reason),p_reference,v_uid); v_delta:=case when p_kind in ('payment','credit','write_off') then p_amount when p_kind='refund' then -p_amount else 0 end; update public.invoices set amount_paid=greatest(0,least(total,amount_paid+v_delta)), status=case when greatest(0,least(total,amount_paid+v_delta))>=total then 'paid' when greatest(0,least(total,amount_paid+v_delta))>0 then 'part_paid' else status end, paid_at=case when greatest(0,least(total,amount_paid+v_delta))>=total then coalesce(paid_at,now()) else null end, updated_at=now() where id=p_invoice; end $$; revoke all on function public.record_invoice_adjustment(uuid,text,numeric,text,text) from public,anon; grant execute on function public.record_invoice_adjustment(uuid,text,numeric,text,text) to authenticated;
